pub(crate) fn transn_offset_for_action_key(
    source_action_key: SourceActionKey,
    source_frame: u8,
) -> Option<Vec3> {
    let index = usize::from(source_frame.saturating_sub(1));
    match source_action_key.as_str() {
        "EscapeF" => ESCAPE_F_TRANSN_OFFSET.get(index).copied(),
        "EscapeB" => ESCAPE_B_TRANSN_OFFSET.get(index).copied(),
        "SpecialAirHi" => SPECIAL_AIR_HI_TRANSN_OFFSET.get(index).copied(),
        "SpecialHi" => SPECIAL_HI_TRANSN_OFFSET.get(index).copied(),
        "TurnRun" => TURN_RUN_TRANSN_OFFSET.get(index).copied(),
        "CliffCatch" => CLIFF_CATCH_TRANSN_OFFSET.get(index).copied(),
        "CliffWait1" => CLIFF_WAIT_TRANSN_OFFSET.get(index).copied(),
        "PassiveStandF" => PASSIVE_STAND_F_TRANSN_OFFSET.get(index).copied(),
        "PassiveStandB" => PASSIVE_STAND_B_TRANSN_OFFSET.get(index).copied(),
        _ => None,
    }
}

